package example

import x.y.MyMessages

/**
 * Converts a message bundle accessor into a plain [String] in the currently
 * selected locale.
 *
 * The `x.y.MyMessages` object is generated by the i18n4k Kotlin Toolchain
 * plugin from the properties files in `src/i18n/x/y`.
 */
fun greeting(name: String): String = MyMessages.sayHello(name)

/** The (localized) title of the example. */
fun title(): String = MyMessages.title.toString()
